    public static List<Order> SortOrdersByProperty(List<Order> objListOrder, string propertyName)
    {
        if (propertyName == "OrderId")
        {
            objListOrder.Sort((x, y) => x.OrderId.CompareTo(y.OrderId));
        }
        else if (propertyName == "OrderDate")
        {
            objListOrder.Sort((x, y) => x.OrderDate.CompareTo(y.OrderDate));
        }
        else
        {
            throw new ArgumentException("Invalid property name");
        }

        return objListOrder;
    }

    public static void GetOrderList(List<Order> objListOrder)
    {
        foreach (var order in objListOrder)
        {
            Console.WriteLine($"OrderId: {order.OrderId}, OrderDate: {order.OrderDate}, Quantity: {order.Quantity}, Total: {order.Total}");
