def find_missing_numbers(nums, k):
    total_sum = sum(range(1, 101))
    expected_sum = total_sum - sum(nums)
    for i in range(1, k + 1):
        actual_sum = 0
        for num in range(1, 101):
            if num not in nums:
                actual_sum += num
        if actual_sum == expected_sum:
            return num
    return None

def find_missing_numbers_q2(nums, k):
    count_dict = {}
    for num in nums:
        if num not in count_dict:
            count_dict[num] = 1
        else:
            count_dict[num] += 1
    for i in range(1, k + 1):
        actual_count = count_dict.get(i, 0)
        if actual_count != i:
            return i
    return None

def find_missing_numbers_q3(nums, k):
    count_dict = {}
    for num in nums:
        if num not in count_dict:
            count_dict[num] = 1
        else:
            count_dict[num] += 1
    count_dict = {num: count - 1 for num, count in count_dict.items() if count > 0}
    for num, count in count_dict.items():
        if count != k:
            return num
    return None

def find_missing_numbers_qk(nums, k):
