class ImageViewerActivity extends AppCompatActivity {

    private ListView listView;
    private TextView textView;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_image_viewer);

        listView = findViewById(R.id.list_view);
        textView = findViewById(R.id.text_view);

        loadImages();
    }

    private void loadImages() {
        // Get the total number of images
        int totalImages = 10; // Replace with your total images count

        // Create a new thread to load images
        Thread thread = new Thread(new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < totalImages; i++) {
                    // Simulate image download
                    try {
                        URL url = new URL("https://example.com/image" + i + ".jpg");
                        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                        connection.setRequestMethod("GET");
                        connection.connect();

                        if (connection.getResponseCode() == 200) {
                            // Write the image to a file
                            File file = new File("image" + i + ".jpg");
                            FileOutputStream fos = new FileOutputStream(file);
                            fos.write(connection.getInputStream().readAllBytes());
                            fos.close();

                            // Update the text view
                            textView.setText("Image " + (i + 1) + ": " + file.getName());
                        } else {
                            // Handle error
                            textView.setText("Error downloading image " + i + ": " + connection.getResponseCode());
                        }
                    } catch (IOException e) {
                        // Handle error
                        textView.setText("Error downloading image " + i + ": " + e.getMessage());
                    }
                }
            }
        });
        thread.start();
    }
}
