import android.app.Activity;
import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.Matrix;
import android.graphics.RectF;
import android.util.Log;

public class MainActivity extends Activity {
    private Button[] buttons;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        buttons = new Button[2];

        // ...

        // Add a new button to resize the image
        Button resizeButton = (Button) findViewById(R.id.resize_button);
        resizeButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Get the current bitmap
                Bitmap bitmap = (Bitmap) listView.getAdapter().getBackground();

                // Get the image URI
                String uri = bitmap.getUri();

                // Use a library like Skia to resize the image
                // Here, we assume you have a library like Skia installed
                Bitmap resizedBitmap = BitmapFactory.decodeFile(uri);

                // Calculate the new size
                RectF rect = new RectF();
                resizedBitmap.getRectF(rect);

                // Resize the image
                Matrix matrix = new Matrix();
                matrix.postScale(0.5f, 0.5f);
                Bitmap resizedBitmap2 = BitmapFactory.decodeFile(uri, matrix);

                // Update the bitmap
                bitmap = resizedBitmap2;

                // Update the image in the list view
                listView.setAdapter(notes);
            }
        });
    }
}
```

Note that this is a simplified example and you may need to modify it to fit your specific needs.

