import unittest
from unittest.mock import Mock

class TestMockAndInjectMocks(unittest.TestCase):

    def test_difference(self):
        # Using @Mock
        mock_object = Mock()
        self.assertEqual(mock_object.method(), None)

        # Using @InjectMocks
        mock_object = Mock(spec=Mock)
        with self.assertRaises(TypeError):
            mock_object.method()

        # Using @InjectMocks with @InjectMocks as decorator
        @Mock
        class TestClass:
            pass
        @InjectMocks
        def test_method(self, test_class):
            self.assertEqual(test_class.method(), None)

if __name__ == '__main__':
