using System;
using System.Collections.Generic;
using System.Linq;

public class Order
{
    public int OrderId { get; set; }
    public DateTime OrderDate { get; set; }
    public int Quantity { get; set; }
    public decimal Total { get; set; }

    public Order(int orderId, DateTime orderDate, int quantity, decimal total)
    {
        OrderId = orderId;
        OrderDate = orderDate;
        Quantity = quantity;
        Total = total;
    }
}

class Program
{
    static void Main()
    {
        List<Order> objListOrder = new List<Order>();
        objListOrder.Add(new Order(1, DateTime.Now, 10, 100.0m));
        objListOrder.Add(new Order(2, DateTime.Now - TimeSpan.FromDays(1), 20, 200.0m));
        objListOrder.Add(new Order(3, DateTime.Now, 30, 300.0m));

        var sortedOrders = objListOrder.OrderBy(o => o.OrderDate).ThenBy(o => o.OrderId).ToList();

        foreach (var order in sortedOrders)
        {
            Console.WriteLine($"OrderId: {order.OrderId}, OrderDate: {order.OrderDate}, Quantity: {order.Quantity}, Total: {order.Total}");
        }
    }
}
