function compareDates(date1, date2) {
    // Get the year, month and day from the input dates
    let year1 = parseInt(date1.split('-')[0]);
    let month1 = parseInt(date1.split('-')[1]);
    let day1 = parseInt(date1.split('-')[2]);

    let year2 = parseInt(date2.split('-')[0]);
    let month2 = parseInt(date2.split('-')[1]);
    let day2 = parseInt(date2.split('-')[2]);

    // Check if both dates are in the past
    if (year1 < year2 && month1 < month2 && day1 < day2) {
        return "The values are not in the past.";
    }
    // Check if date1 is greater than date2
    else if (year1 < year2 && month1 < month2 && day1 > day2) {
        return "Date1 is greater than date2.";
    }
    // Check if date1 is less than date2
    else if (year1 > year2 && month1 > month2 && day1 < day2) {
        return "Date1 is less than date2.";
    }
    // If none of the above conditions are met, it means date1 and date2 are not in the past
    else {
        return "Both dates are not in the past.";
    }
}

