import os

def check_ssh_key_permissions():
    # Get the current permissions of the .pem file
    current_permissions = os.stat(".pem").st_mode

    # Try to set the permissions to 0644 (owner has read, write, and execute, group has read)
    try:
        new_permissions = os.stat(".pem").st_mode | 0o644

        # Check if the permissions are correct
        if new_permissions == current_permissions:
            print("Permissions are correct: .pem file is readable by the owner, group, and others.")
        else:
            print("Permissions are incorrect: .pem file is not readable by the owner, group, or others.")
    except OSError:
        print("Permission denied: unable to set new permissions.")

