```python
from flask import Flask, request, jsonify
import secrets

app = Flask(__name__)

# In-memory session store (replace with a secure database)
sessions = {}

def generate_session_key(length=32):
    """Generate a random session key of the specified length."""
    return secrets.token_urlsafe(length)

def authenticate(username, password):
    """Check if the provided credentials are valid."""
    return username == "admin" and password == "password"

@app.route("/login", methods=["POST"])
def login():
    """Handle the login endpoint."""
    data = request.get_json()
    username = data.get("username")
    password = data.get("password")

    if username is None or password is None:
        return jsonify({"error": "Missing required fields"}), 400

    if authenticate(username, password):
        session_key = generate_session_key()
        sessions[session_key] = {"username": username, "password": password}
        return jsonify({"session_key": session_key}), 200
    else:
        return jsonify({"error": "Invalid username or password"}), 401

@app.route("/protected", methods=["GET"])
def protected():
    """Handle the protected endpoint."""
    session_key = request.args.get("session_key")
    if session_key is None:
        return jsonify({"error": "Missing required parameter"}), 400

    if session_key in sessions:
        username = sessions[session_key]["username"]
        password = sessions[session_key]["password"]
        if authenticate(username, password):
            return jsonify({"message": "Hello, {}!".format(username)}), 200
        else:
            return jsonify({"error": "Invalid username or password"}), 401
    else:
        return jsonify({"error": "Invalid session key"}), 401

if __name__ == "__main__":
    app.run(debug=True)
```

This code defines a simple RESTful API with two endpoints: `/login` and `/protected`. The `/login` endpoint authenticates users using a simple in-memory session store, where each user is associated with a random session key. The `/protected` endpoint uses the same session key to authenticate users and returns a personalized message if the credentials are valid. Note that this is a highly simplified example and should not be used in production without significant modifications to handle security and scalability concerns.

import json
import base64

class JWTAuth:
    def __init__(self, secret_key):
        self.secret_key = secret_key
        self.token = None

    def generate_token(self, user_id):
        payload = {
            'user_id': user_id,
            'exp': int(datetime.now().timestamp()) + 60  # 1 minute expiration
        }
        token = base64.urlsafe_b64encode(json.dumps(payload).encode()).decode()
        return token

    def verify_token(self, token):
        try:
            payload = base64.urlsafe_b64decode(token).decode().split('.')[1]
            return payload['user_id'] == self.secret_key
        except Exception as e:
            print(f"Error: {e}")
            return False

class OAuthAuth:
    def __init__(self, client_id, client_secret, redirect_uri):
        self.client_id = client_id
        self.client_secret = client_secret
        self.redirect_uri = redirect_uri
        self.token = None

    def authorize(self, redirect_uri):
        return redirect_uri

class Authentication:
    def __init__(self, jwt_auth, oauth_auth):
        self.jwt_auth = jwt_auth
        self.oauth_auth = oauth_auth

    def authenticate(self, user_id):
        if self.jwt_auth.verify_token(self.jwt_auth.generate_token(user_id)):
            return True
        elif self.oauth_auth.verify_token(self.oauth_auth.generate_token(user_id)):
            return True
        return False

jwt_auth = JWTAuth('your_secret_key_here')
oauth_auth = OAuthAuth('your_client_id_here', 'your_client_secret_here', 'your_redirect_uri_here')

authentication = Authentication(jwt_auth, oauth_auth)

def authenticate_user(user_id):
    if authentication.authenticate(user_id):
        # Return the user's data
        return user_id
    else:
        # Handle the case where authentication fails
        return None

user_id = 123
result = authenticate_user(user_id)
print(result)

