import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the URL:");
        String url = scanner.nextLine();
        System.out.println("Enter the method (GET, POST, PUT, DELETE, CONNECT, HEAD, OPTIONS, PATCH):");
        String method = scanner.nextLine();

        URI uri = URI.create(url);
        HttpClient client = HttpClient.newHttpClient();

        switch (method) {
            case "GET":
                HttpRequest request = HttpRequest.newBuilder()
                        .uri(uri)
                        .GET()
                        .build();
                try (HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString())) {
                    System.out.println(response.body());
                } catch (Exception e) {
                    System.out.println("Error: " + e.getMessage());
                }
                break;
            case "POST":
                HttpRequest request = HttpRequest.newBuilder()
                        .uri(uri)
                        .method("POST", HttpRequest.BodyPublishers.ofString("Hello, World!"))
                        .build();
                try (HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString())) {
                    System.out.println(response.body());
                } catch (Exception e) {
                    System.out.println("Error: " + e.getMessage());
                }
                break;
            default:
                System.out.println("Invalid method. Supported methods are GET, POST, PUT, DELETE, CONNECT, HEAD, OPTIONS, PATCH.");
        }
    }
}

