```python
# A mixin is a class that provides a set of methods or attributes that can be used by other classes without being a subclass.
# It's useful when you want to share common functionality across multiple classes without forcing them to inherit from the mixin.

class Logger:
    def log(self, message):
        # A simple logging class with a log method
        pass

class ConsoleLogger(Logger):
    def log(self, message):
        print(message)

class FileLogger(Logger):
    def log(self, message):
        # A logging class that writes to a file
        with open('log.txt', 'a') as file:
            file.write(message + '\n')

# Now, let's create a class that uses the Logger mixin
class MyService:
    def __init__(self):
        self.logger = None

    def do_something(self):
        self.logger.log('Something happened')

# We can use the Logger mixin without having to subclass it
class MyServiceWithLogger:
    def __init__(self):
        self.logger = ConsoleLogger()

    def do_something(self):
        self.logger.log('Something happened')

# But, we can't use the Logger mixin directly as a subclass
class MyServiceWithLoggerSubclass:
    def __init__(self):
        self.logger = FileLogger()

    def do_something(self):
        self.logger.log('Something happened')

# In this case, we can use composition instead of multiple inheritance
class MyServiceWithComposition:
    def __init__(self, logger):
        self.logger = logger

    def do_something(self):
        self.logger.log('Something happened')

# The Logger mixin is useful when you want to share common functionality across multiple classes without forcing them to inherit from the mixin.
# It's also useful when you want to avoid using multiple inheritance, which can lead to tight coupling between classes.
```

This code demonstrates the use of the `Logger` mixin in different ways, including as a class attribute, a method, and as a subclass. It also shows the difference between using composition instead of multiple inheritance.

