To call a REST web service API from JavaScript, you can use the Fetch API, which is a built-in function in modern browsers. Here's an example of how to do it:

```javascript
// Define the URL of the API endpoint
const apiUrl = 'https://api.example.com/endpoint';

// Define the data to be sent with the request
const data = {
  key: 'value'
};

// Create a new Fetch request
fetch(apiUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(data)
})
  .then(response => response.json())
  .then(data => console.log(data))
  .catch(error => console.error(error));
```

This code sends a POST request to the specified API endpoint with the provided data. The response from the API will be parsed as JSON and logged to the console.

```python
import requests

def request_url(url, method, data=None, headers=None):
    try:
        response = requests.request(method, url, data=data, headers=headers)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
        return None

# Example usage:
url = "https://api.example.com/myMethodName"
data = {"key1": "value1", "key2": "value2"}
headers = {"Content-Type": "application/json"}

response = request_url(url, "POST", data, headers)
if response is not None:
    print(response)
