```python
import Kubernetes
from Kubernetes import Client

class Service:
    def __init__(self, name, namespace, endpoint, ip):
        self.name = name
        self.namespace = namespace
        self.endpoint = endpoint
        self.ip = ip

class Pod:
    def __init__(self, name, namespace):
        self.name = name
        self.namespace = namespace

class ServiceLocation:
    def __init__(self, namespace, service):
        self.namespace = namespace
        self.service = service

class ClusterIP:
    def __init__(self, ip):
        self.ip = ip

class KubernetesService:
    def __init__(self, name, namespace, endpoint, ip):
        self.name = name
        self.namespace = namespace
        self.endpoint = endpoint
        self.ip = ip

class KubernetesPod:
    def __init__(self, name, namespace):
        self.name = name
        self.namespace = namespace

def create_service(namespaceA, service_name, service_endpoint, service_ip):
    k8s = Kubernetes.Client()
    service = KubernetesService(service_name, namespaceA, service_endpoint, service_ip)
    return service

def create_pod(namespaceA, pod_name):
    pod = KubernetesPod(pod_name, namespaceA)
    return pod

def get_endpoint(service, namespace):
    endpoint = KubernetesEndpoints()
    endpoint.subsets.append({
        'targetRef': {
            'kind': Kubernetes.Service,
            'namespace': namespace,
            'name': service.name,
            'apiVersion': 'v1'
        },
        'ports': [{
            'name': 'http',
            'port': 3000
        }]
    })
    return endpoint

def get_cluster_ip(namespace):
    return ClusterIP('192.168.1.1')

def create_endpoints(namespaceA, service_name, service_endpoint, service_ip):
    endpoint = get_endpoint(service_name, namespaceA)
    endpoint.ip = service_ip
    return endpoint

def main():
    namespaceA = 'default'
    service_name = 'serviceX'
    service_endpoint = 'http://serviceX'
    service_ip = '192.168.1.1'

    pod = create_pod(namespaceA, 'pod1')
    endpoint = get_endpoint(service_name, namespaceA)
    endpoint.ip = service_ip
    cluster_ip = get_cluster_ip(namespaceA)
    cluster_ip.ip = service_ip

    service = create_service(namespaceA, service_name, service_endpoint, service_ip)
    pod.located_in = KubernetesServiceLocation(namespaceA, service)
    endpoint.located_in = KubernetesServiceLocation(namespaceA, service)
    cluster_ip.located_in = KubernetesServiceLocation(namespaceA, service)

    k8s = Kubernetes.Client()
    k8s.create_namespaced_pod(namespaceA, pod)
    k8s.create_namespaced_endpoint(namespaceA, endpoint)
    k8s.create_namespaced_cluster_ip(namespaceA, cluster_ip)

if __name__ == "__main__":
    main()
```

