import git

def find_deleted_file():
    repo = git.Repo('.')
    for ref in repo.head.refspec.split('\n'):
        head = git.Repo('..', merge=ref)
        for commit in head.commit_list:
            if commit.message.startswith('Deleted file:'):
                print(f"Commit {commit.id}: {commit.message.strip()}")
                return

find_deleted_file()
```
